<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= e($report['title']) ?></title><link rel="icon" href="<?= e(asset('img/ndc-ghana-logo.svg')) ?>"><link rel="stylesheet" href="<?= e(asset('css/shared/reports.css').'?v=1') ?>"><script defer src="<?= e(asset('js/shared/reports.js').'?v=1') ?>"></script></head>
<body><header class="report-header"><div class="report-identity"><img src="<?= e(asset('img/ndc-ghana-logo.svg')) ?>" alt="NDC Ghana" width="35" height="51"><div><span>National Democratic Congress &middot; Ghana</span><h1><?= e($report['title']) ?></h1><p><?= number($report['total']) ?> matching records &middot; Generated <?= e($report['generated_at']) ?></p></div></div><div class="report-actions"><?php if(!empty($report['back_url'])): ?><a href="<?= e($report['back_url']) ?>">Back to results</a><?php endif; ?><button type="button" data-print-report>Print / Save PDF</button></div></header>
<section class="report-criteria" aria-labelledby="report-criteria-title"><h2 id="report-criteria-title">Applied criteria</h2><dl><?php foreach($report['criteria'] as $key=>$value): ?><dt><?= e($key) ?></dt><dd><?= e($value) ?></dd><?php endforeach; if(!$report['criteria']): ?><dt>Scope</dt><dd>All matching records</dd><?php endif; ?></dl></section>
<main><div class="report-table-wrap" role="region" aria-label="Report records" tabindex="0"><table><thead><tr><?php foreach($report['columns'] as $column): ?><th scope="col"><?= e($column) ?></th><?php endforeach; ?></tr></thead><tbody><?php foreach($report['records'] as $record): ?><tr><?php foreach($record as $value): ?><td><?= e($value) ?></td><?php endforeach; ?></tr><?php endforeach; if(!$report['records']): ?><tr><td colspan="<?= count($report['columns']) ?>">No matching records.</td></tr><?php endif; ?></tbody></table></div></main>
<footer><?= e($report['notice']??'Staff report. Figures reflect the applied filters and generation time.') ?></footer></body></html>
